"use strict";(globalThis.webpackChunkztools_docs=globalThis.webpackChunkztools_docs||[]).push([[91410],{23265(o){o.exports=JSON.parse('{"id":"eatthis","name":"Eat This","url":"https://eatthis.aoneahsan.com","platforms":["Web"],"logo":"/ecosystem/eatthis.svg","card":"Your calorie number, turned into food you can actually buy.","title":"Eat This: from a nutrition number to something on your plate","intro":"Eat This lets you look for food by nutrient, by how you feel or by the time of day. It shows how much of a nutrient one serving gives.","sections":[["Why after a ZTools calculator?","The ZTools calorie and macronutrient calculators give you a target. Eat This answers the next question: which food gets you there, and how much of it."],["Does it help on a budget?","Yes. It points out a cheap pick among the foods that fit."],["Is it medical advice?","No. Eat This also tells you when a question belongs with a doctor."]]}')}}]);